<?php
namespace App\Http\Controllers; use Illuminate\Http\Request;
abstract class CrudController extends Controller { protected $service; protected $model; protected function rules():array{return [];} public function index(){return response()->json($this->service->index(new $this->model));} public function store(Request $r){$data=$r->validate($this->rules());return response()->json($this->service->store(new $this->model,$data),201);} public function show($id){return response()->json($this->service->show(new $this->model,$id));} public function update(Request $r,$id){$data=$r->validate($this->rules());return response()->json($this->service->update(new $this->model,$id,$data));} public function destroy($id){$this->service->destroy(new $this->model,$id);return response()->noContent();} }
